pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address[] internal depositors;

    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 depositAmt, address depositor1, address depositor2) public {
        vm.assume(depositor1 != depositor2 && depositor1 != address(0) && depositor2 != address(0));
        vm.assume(depositAmt > 0 && depositAmt <= address(this).balance);

        // Fund and deposit from two distinct addresses
        vm.deal(depositor1, depositAmt);
        vm.prank(depositor1);
        c.Deposit{value: depositAmt}();

        vm.deal(depositor2, depositAmt);
        vm.prank(depositor2);
        c.Deposit{value: depositAmt}();

        // Read total supply of ETH in the system: contract balance + sum of tracked balances
        uint256 trackedBal1 = c.balances(depositor1);
        uint256 trackedBal2 = c.balances(depositor2);
        uint256 contractBal = address(c).balance;
        uint256 totalInSystem = trackedBal1 + trackedBal2 + contractBal;

        // Reference should always have totalInSystem equal to total deposited (2 * depositAmt)
        // Mutant reduces tracked balance without sending ETH, so totalInSystem decreases
        assertTrue(totalInSystem == 2 * depositAmt);
    }
}

