pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 depositAmount, uint256 collectAmount, uint8 seed) public {
        // Bound amounts to avoid overflow and ensure collectAmount <= minSum
        depositAmount = bound(depositAmount, 1, 100 ether);
        collectAmount = bound(collectAmount, 0, 5 ether);

        // We'll use seed to generate distinct actors from allowed range to avoid address(0) collision
        address depositor = address(uint160(uint256(keccak256(abi.encode(seed, 1)))));
        address collector = address(uint160(uint256(keccak256(abi.encode(seed, 2)))));

        // Exclude address(0) from being a fuzzed actor to avoid masking bug
        vm.assume(depositor != address(0));
        vm.assume(collector != address(0));

        // Initialize contract and set MinSum to 1 ether
        c.SetMinSum(1 ether);
        c.Initialized();

        // Deposit from depositor
        vm.deal(depositor, depositAmount);
        vm.prank(depositor);
        c.Deposit{value: depositAmount}();

        // Deposit from collector to ensure they have balance for collect
        vm.deal(collector, depositAmount);
        vm.prank(collector);
        c.Deposit{value: depositAmount}();

        // Attempt collect from collector
        vm.prank(collector);
        try c.Collect(collectAmount) {} catch {}

        // The invariant: address(0) must have zero balance because no depositor is address(0)
        // The bug credits address(0) instead of sender, so it accumulates balance
        assertTrue(c.balances(address(0)) == 0);
    }
}

