pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amt, uint256 collectAmt, uint8 seed) public {
        // Restrict amounts to avoid overflow (realistic deposit/collect range)
        amt = bound(amt, 1, 1000 ether);
        collectAmt = bound(collectAmt, 1, 1000 ether);

        // Use seed to generate pseudorandom actors to explore many depositors
        address actor1 = address(uint160(uint256(keccak256(abi.encode(seed)))));
        address actor2 = address(uint160(uint256(keccak256(abi.encode(seed ^ 1)))));

        // Ensure actors are not special addresses
        vm.assume(actor1 != address(0) && actor2 != address(0));
        vm.assume(actor1 != address(c) && actor2 != address(c));

        // Initialize the contract
        c.Initialized();

        // Track total deposited ether via Deposit() and total collected via successful Collect()
        uint256 totalDeposited = 0;
        uint256 totalCollected = 0;

        // Actor1 deposits
        vm.deal(actor1, amt);
        vm.prank(actor1);
        c.Deposit{value: amt}();
        totalDeposited += amt;

        // Actor2 deposits a different amount
        uint256 amt2 = amt + 1; // avoid identical amounts
        vm.deal(actor2, amt2);
        vm.prank(actor2);
        c.Deposit{value: amt2}();
        totalDeposited += amt2;

        // Try collect from actor1 if enough balance and above MinSum
        uint256 minSum = c.MinSum();
        if (c.balances(actor1) >= minSum && c.balances(actor1) >= collectAmt) {
            // Wrap in try/catch because the low-level call in Collect may fail, we only count successful collects
            vm.prank(actor1);
            try c.Collect(collectAmt) {
                totalCollected += collectAmt;
            } catch {
                // Collect reverted (e.g., failed ether send), don't count
            }
        }

        // Try collect from actor2 if enough balance and above MinSum
        uint256 collectAmt2 = collectAmt + 1;
        if (c.balances(actor2) >= minSum && c.balances(actor2) >= collectAmt2) {
            vm.prank(actor2);
            try c.Collect(collectAmt2) {
                totalCollected += collectAmt2;
            } catch {}
        }

        // Sum all relevant balances (addresses that participated plus address(0) which the bug writes to)
        uint256 sumBalances = c.balances(actor1) + c.balances(actor2) + c.balances(address(0));
        uint256 contractBalance = address(c).balance;

        // Rule: sumBalances + contractBalance == totalDeposited - totalCollected
        // (Since no ether is lost or created except via Deposit/Collect)
        assertTrue(sumBalances + contractBalance == totalDeposited - totalCollected);
    }
}

