pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 depositAmount, uint256 collectAmount, address depositor, address collector) public {
        // Restrict amounts to avoid overflow and ensure collect is feasible
        vm.assume(depositAmount >= 1 ether);
        vm.assume(depositAmount <= 1000 ether);
        vm.assume(collectAmount >= 1 ether);
        vm.assume(collectAmount <= depositAmount);
        // Ensure actors are distinct and not zero address (zero address is where bug credits)
        vm.assume(depositor != address(0));
        vm.assume(collector != address(0));
        vm.assume(depositor != collector);
        // Initialize and set MinSum
        c.SetMinSum(1 ether);
        c.Initialized();

        // Depositor deposits
        vm.deal(depositor, depositAmount);
        vm.prank(depositor);
        c.Deposit{value: depositAmount}();

        // Record contract balance before collect by address(0)
        uint256 balBefore = address(c).balance;

        // Collector (address(0)) attempts to Collect; in reference, address(0) has 0 balance, so Collect reverts or does nothing.
        // In buggy version, address(0) has balance because deposits are credited there.
        vm.prank(address(0));
        try c.Collect(collectAmount) {
            // If it succeeds (buggy case), check contract balance decreased exactly by collectAmount
            uint256 balAfter = address(c).balance;
            // In reference, this never succeeds, so the assertion holds vacuously.
            // In buggy version, address(0) drains ETH it didn't deposit, so contract balance decreases
            // even though no successful Collect should happen for a non-depositor.
            assertEq(balBefore - balAfter, collectAmount);
        } catch {
            // If it reverts (reference case), no ETH moved, balance unchanged.
            assertEq(address(c).balance, balBefore);
        }
    }
}

